from main.domain.entities.authzen import (
    CedarlingRequest,
    Decision,
    Resource,
    EntityMapping,
    Token,
)


class TestCedarlingIntegration:
    def test_initialized(self, cedarling_instance):
        assert cedarling_instance is not None
        assert cedarling_instance.get_cedarling_instance() is not None

    def test_generate_resource(self, cedarling_instance):
        resource = Resource(
            cedar_entity_mapping=EntityMapping(entity_type="test", id="test"),
            attributes={"a": "b"},
        )
        resource_entity = cedarling_instance.generate_resource(resource)
        assert resource_entity is not None

    def test_authorization(self, cedarling_instance):
        resource = Resource(
            cedar_entity_mapping=EntityMapping(
                entity_type="Jans::Issue", id="random_id"
            ),
            attributes={
                "org_id": "some_long_id",
                "country": "US",
            },
        )
        tokens = [
            Token(
                mapping="Jans::Access_Token",
                payload="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..7n4vE60lisFLnEFhVwYMOPh5loyLLtPc07sCvaFI-Ik",  # noqa: S105  # gitleaks:allow
            ),
            Token(
                mapping="Jans::Id_Token",
                payload="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..RgCuWFUUjPVXmbW3ExQavJZH8Lw4q3kGhMFBRR0hSjA",  # noqa: S105  # gitleaks:allow
            ),
            Token(
                mapping="Jans::Userinfo_Token",
                payload="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..t6p8fYAe1NkUt9mn9n9MYJlNCni8JYfhk-82hb_C1O4",  # noqa: S105  # gitleaks:allow
            ),
        ]
        request = CedarlingRequest(
            tokens=tokens,
            action='Jans::Action::"Update"',
            resource=resource,
            context={},
        )
        result = cedarling_instance.authorize(request)
        assert result.decision is True
        assert "request_id" in result.context
        assert "policy_store_id" in result.context
